        entrada_.clear();
        char c = '?';
        while (entrada_.get(c)) {
            if (c == ';') return true;
        }
        if (entrada_.bad() || !entrada_.eof()) throw std::runtime_error("Fallo del flujo");
        return false;
    }

private:
    std::istringstream entrada_;
    bool lleno_ = false;
    Token guardado_{final_texto, 0, ""};
};

int resultado_en_dominio(int candidato) {
    if (candidato < -100 || candidato > 100) {
        throw std::runtime_error("Resultado fuera de dominio");
    }
    return candidato;
}

void presentar(const Token& token) {
    if (token.clase == final_texto) std::cout << "Fin\n";
    else if (token.clase == numero) std::cout << "Numero: " << token.valor << "\n";
    else if (token.clase == nombre) std::cout << "Nombre: " << token.texto << "\n";
    else if (token.clase == declaracion) std::cout << "Palabra: crea\n";
    else std::cout << "Signo: " << token.clase << "\n";
}

void inspeccionar(const std::string& texto) {
    Lector_tokens lector{texto};
    try {
        while (true) {
            const Token token = lector.leer();
            presentar(token);
            if (token.clase == final_texto) break;
        }
    } catch (const std::runtime_error& error) {
        std::cout << "Error: " << error.what() << "\n";
    }
}

int main() {
    std::cout << "Caso 1\n";
    Lector_tokens lector{"Pasillo_2*4;"};
    const Token primero = lector.leer();
    lector.devolver(primero);
    const Token recuperado = lector.leer();
    std::cout << "Reservado: " << recuperado.texto << "\n";
    while (true) {
        const Token token = lector.leer();
        presentar(token);
        if (token.clase == final_texto) break;
    }
    const std::vector<std::string> pruebas{"n;", "Crea;", "crea;", "A1_B;", "abcdefghijkl;", "abcdefghijklm;", "_A;", "solo"};
    int caso = 2;
    for (const std::string& texto : pruebas) {
        std::cout << "Caso " << caso << "\n";
        inspeccionar(texto);
        ++caso;
    }
    return 0;
}
